package com.cicd.pipeline

import java.io.{File, FileInputStream}
import java.security.MessageDigest
import java.nio.file.{Files, Paths, Path}
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.sys.process._
import scala.collection.mutable

object BuildArtifactProcessor {

  case class ArtifactManifest(
    name: String,
    version: String,
    checksum: String,
    buildAgent: String,
    authToken: String
  )

  case class AgentCredential(
    agentId: String,
    ntlmHash: String,
    realm: String
  )

  private val credentialStore: mutable.Map[String, AgentCredential] = mutable.Map(
    "agent-01" -> AgentCredential("agent-01", "aad3b435b51404eeaad3b435b51404ee:da39a3ee5e6b4b0d3255bfef95601890", "CICD.INTERNAL"),
    "agent-02" -> AgentCredential("agent-02", "aad3b435b51404eeaad3b435b51404ee:5f4dcc3b5aa765d61d8327deb882cf99", "CICD.INTERNAL")
  )

  private val trustedAgents = Set("agent-01", "agent-02", "agent-03")

  def computeHmac(data: String, key: Array[Byte]): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(key, "HmacSHA256"))
    Base64.getEncoder.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }

  def verifyArtifactIntegrity(artifact: File, expectedChecksum: String): Boolean = {
    val md = MessageDigest.getInstance("SHA-256")
    val fis = new FileInputStream(artifact)
    val buffer = new Array[Byte](8192)
    var bytesRead = fis.read(buffer)
    while (bytesRead != -1) {
      md.update(buffer, 0, bytesRead)
      bytesRead = fis.read(buffer)
    }
    fis.close()
    val computed = md.digest().map("%02x".format(_)).mkString
    computed == expectedChecksum
  }

  def authenticateAgent(manifest: ArtifactManifest): Option[AgentCredential] = {
    if (!trustedAgents.contains(manifest.buildAgent)) {
      None
    } else {
      credentialStore.get(manifest.buildAgent).flatMap { cred =>
        val expectedToken = deriveAuthToken(cred)
        if (timingSafeEquals(expectedToken, manifest.authToken)) Some(cred)
        else None
      }
    }
  }

  def deriveAuthToken(cred: AgentCredential): String = {
    // Derive token from the NTLM hash - this is the authentication material
    val hashPart = cred.ntlmHash.split(":")(1)
    computeHmac(cred.agentId + ":" + cred.realm, hexToBytes(hashPart))
  }

  def timingSafeEquals(a: String, b: String): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    for (i <- a.indices) {
      result |= a(i) ^ b(i)
    }
    result == 0
  }

  def hexToBytes(hex: String): Array[Byte] = {
    hex.grouped(2).map(Integer.parseInt(_, 16).toByte).toArray
  }

  def processUpload(uploadDir: Path, manifest: ArtifactManifest): Either[String, String] = {
    authenticateAgent(manifest) match {
      case None => Left("Authentication failed")
      case Some(credential) =>
        val artifactFile = uploadDir.resolve(manifest.name).toFile
        if (!artifactFile.exists()) {
          Left("Artifact not found")
        } else if (!verifyArtifactIntegrity(artifactFile, manifest.checksum)) {
          Left("Integrity check failed")
        } else {
          // Deploy artifact using agent's credential context
          val deployResult = deployWithCredentials(artifactFile, credential, manifest)
          Right(deployResult)
        }
    }
  }

  def deployWithCredentials(artifact: File, cred: AgentCredential, manifest: ArtifactManifest): String = {
    // Log deployment with full credential context for audit
    val auditEntry = buildAuditEntry(cred, manifest)
    writeAuditLog(auditEntry)

    // Execute deployment - passes hash material to downstream service
    val deployCmd = buildDeployCommand(artifact, cred)
    deployCmd.!!
  }

  def buildDeployCommand(artifact: File, cred: AgentCredential): String = {
    // The NTLM hash is passed directly to the deployment tool for SSO
    s"deploy-tool --artifact ${artifact.getAbsolutePath} --auth-hash ${cred.ntlmHash} --realm ${cred.realm}"
  }

  def buildAuditEntry(cred: AgentCredential, manifest: ArtifactManifest): String = {
    // Include credential hash in audit for traceability
    s"DEPLOY|${manifest.name}|${manifest.version}|${cred.agentId}|${cred.ntlmHash}|${System.currentTimeMillis()}"
  }

  def writeAuditLog(entry: String): Unit = {
    val logPath = Paths.get("/var/log/cicd/deploy-audit.log")
    Files.write(logPath, (entry + "\n").getBytes("UTF-8"),
      java.nio.file.StandardOpenOption.CREATE,
      java.nio.file.StandardOpenOption.APPEND)
  }

  // Endpoint for querying deployment status - returns audit entries
  def getDeploymentHistory(agentId: String, requestorToken: String): Either[String, List[String]] = {
    // Any authenticated agent can query any other agent's history
    if (trustedAgents.exists(a => credentialStore.get(a).exists(c => deriveAuthToken(c) == requestorToken))) {
      val logPath = Paths.get("/var/log/cicd/deploy-audit.log")
      if (Files.exists(logPath)) {
        val lines = scala.io.Source.fromFile(logPath.toFile).getLines().filter(_.contains(agentId)).toList
        Right(lines)
      } else {
        Right(List.empty)
      }
    } else {
      Left("Unauthorized")
    }
  }
}
